// 08/10: categorias ajustadas — 'outro' entra em 'conversa'; compromissos/agenda contam como lembrete; listas/notas contam como tarefa.
const e = $input.first().json || {};
const texto = String(e.texto_usuario || '').slice(0, 1500);
if (!texto.trim()) return [];
const tipos = (Array.isArray(e.acoes) ? e.acoes : []).map(a => String((a && a.tipo) || ''));
const grupo = t => /registrar_transacao|apagar_transacao|editar_ultimo|desfazer_ultimo/.test(t) ? 'gasto'
  : /conta|assinatura|recorrente|recebivel/.test(t) ? 'conta'
  : /lembrete|compromisso|agenda/.test(t) ? 'lembrete'
  : /tarefa|nota|lista|projeto/.test(t) ? 'tarefa'
  : 'conversa';
let intencao = 'conversa';
if (tipos.length) { const gs = tipos.map(grupo); intencao = ['gasto', 'conta', 'lembrete', 'tarefa', 'conversa'].find(o => gs.includes(o)); }
const questions = {
  intencao: { type: 'choice', instructions: 'O que a pessoa quer com esta mensagem enviada ao assistente pessoal no WhatsApp? Escolha pelo pedido principal.', criteria: {
    gasto: 'Registrar, corrigir ou apagar um gasto, compra, pagamento feito ou dinheiro recebido (inclui foto de cupom ou comprovante)',
    conta: 'Cadastrar, pagar, mudar ou cancelar uma conta a pagar, boleto, parcela, assinatura ou valor a receber',
    lembrete: 'Criar, confirmar, adiar ou cancelar um lembrete, compromisso ou evento de agenda com dia ou horario',
    tarefa: 'Criar, concluir ou mudar uma tarefa, lista ou item de lista, ou uma anotacao',
    conversa: 'Qualquer outra coisa: pergunta, consulta de gastos ou agenda, saudacao, agradecimento, orcamento, carro, rastreio, cambio, memoria ou conversa'
  } },
  voz: { type: 'choice', instructions: 'Qual assistente deve responder?', criteria: {
    dyno: 'Dinheiro: gastos, receitas, contas, orcamento, extrato, relatorios financeiros, cambio, plano e conta do Dyno, saudacoes',
    dina: 'Agenda e rotina: lembretes, compromissos, tarefas, listas, horarios, rastreio de encomendas, carro'
  } },
  simples: { type: 'noul', instructions: 'A mensagem e simples o bastante para um modelo pequeno responder sem raciocinio?', criteria: {
    'true': 'Mensagem curta e direta, com uma unica acao obvia (ex.: registrar um gasto, agradecer, confirmar)',
    'false': 'Pede analise, varias acoes, contexto, duvida ou calculo'
  } }
};
return [{ json: { tarefa: 'decisao', origem: 'sombra_cerebro', autor: e.autor || null, decisao: { state: { mensagem: texto, tem_imagem: !!e.imagem, tem_pdf: !!e.pdf }, questions }, _atual: { voz: e.voz || 'dyno', intencao } } }];

const a = $('Montar decisão').first().json;
const r = $input.first().json || {};
if (r.provedor === 'desligado') return [];
const j = r.json || {};
const v = (k, c) => (j[k] && j[k][c] !== undefined) ? j[k][c] : null;
return [{ json: { p: { autor: a.autor, voz_atual: a._atual.voz, intencao_atual: a._atual.intencao, voz_jev: v('voz', 'valor'), voz_conf: v('voz', 'confianca'), intencao_jev: v('intencao', 'valor'), intencao_conf: v('intencao', 'confianca'), simples_jev: v('simples', 'valor'), simples_prob: v('simples', 'probabilidade'), ms: r.ms || null, erro: r.ok ? null : String(r.erro || r.motivo || 'falha') } } }];
